        color: var(--primary);
        transition: rotate 0.3s ease;
      }·
      .store-select:open::picker-icon {
        rotate: 180deg;
      }·
      .store-select::picker(select) {
        margin-top: 6px;
        padding: 6px;
        border: 1px solid var(--secondary);
        border-radius: 8px;
        background: white;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
        opacity: 0;
        translate: 0 -6px;
        transition:
          opacity 0.25s ease,
          translate 0.25s ease,
          display 0.25s allow-discrete,
          overlay 0.25s allow-discrete;
      }·
      .store-select:open::picker(select) {
        opacity: 1;
        translate: 0 0;
      }·
      @starting-style {
        .store-select:open::picker(select) {
          opacity: 0;
          translate: 0 -6px;
        }
      }·
      .store-select option {
        padding: 8px 12px;
        border-radius: 4px;
